query PlayoffGetGolfTournamentGroups($input: GetGolfTournamentGroupsInput!) {
  getGolfTournamentGroups(input: $input) {
    groups {
      ...PlayoffGetGolfTournamentGroupsFieldsQuery
    }
  }
}
fragment PlayoffGetGolfTournamentGroupsFieldsQuery on GolfGroup {
  teams {
    groupId
    l1Course
    teamId
    players {
      id
      lastName
      firstName
    }
    roundScores {
      roundNo
      holes {
        holeOrder
        holePar
        holeNumber
        holeStrokes
      }
    }
  }
}
